<template><div class="editor-panel"><div class="section"><h3 class="section-title">Tipo de modal</h3><div class="tabs"><button v-for="tab in typeTabs" :key="tab.value" class="tab-btn" :class="{active:activeType===tab.value}" @click="activeType=tab.value">{{tab.label}}</button></div></div><div class="divider"></div><div class="section"><h3 class="section-title">Propiedades</h3><div class="controls-grid"><SliderControl v-model="width" label="Ancho" :min="320" :max="640" unit="px"/><SliderControl v-model="borderRadius" label="Border radius" :min="0" :max="24" unit="px"/><ColorPicker v-model="overlayColor" label="Color del overlay"/><SliderControl v-model="padding" label="Padding" :min="12" :max="40" unit="px"/><SliderControl v-model="titleSize" label="Tamaño del título" :min="14" :max="24" unit="px"/><SelectControl v-model="titleWeight" label="Peso del título" :options="weightOptions"/></div><p class="helper">El overlay es la capa semitransparente que cubre el contenido detrás del modal. Se mostrará en la previsualización central.</p></div></div></template>
<script setup>
import {computed} from 'vue';import {useThemeStore} from '@/stores/themeStore.js';import {useAppStore} from '@/stores/appStore.js';import SliderControl from '@/components/common/SliderControl.vue';import SelectControl from '@/components/common/SelectControl.vue';import ColorPicker from '@/components/common/ColorPicker.vue';const t=useThemeStore(),a=useAppStore();const typeTabs=[{value:'confirm',label:'Confirmación'},{value:'info',label:'Información'},{value:'error',label:'Error'},{value:'form',label:'Formulario'}];const weightOptions=[400,500,600,700].map(v=>({value:v,label:String(v)}));const activeType=computed({get:()=>a.componentSelection.modals,set:v=>a.setComponentSelection('modals',v)});const b=p=>computed({get:()=>t.theme.modals[p],set:v=>t.updateModal(p,v)});const width=b('width'),borderRadius=b('borderRadius'),overlayColor=b('overlayColor'),padding=b('padding'),titleSize=b('titleSize'),titleWeight=b('titleWeight')
</script><style scoped>.editor-panel{display:flex;flex-direction:column;gap:24px;padding:16px}.section{display:flex;flex-direction:column;gap:12px}.section-title{font-size:14px;font-weight:600;color:var(--tool-text,#334155);margin:0}.tabs{display:flex;flex-wrap:wrap;gap:8px}.tab-btn{padding:7px 11px;background:#fff;border:1px solid #d1d5db;border-radius:6px;font-size:12px;cursor:pointer;color:#475569}.tab-btn.active{background:#eff6ff;border-color:var(--tool-accent,#2563eb);color:var(--tool-accent,#2563eb);font-weight:600}.controls-grid{display:grid;grid-template-columns:1fr;gap:14px}.helper{font-size:12px;color:#64748b;line-height:1.45}.divider{height:1px;background:#e5e7eb}</style>